-- Run this in the Supabase SQL Editor any time after
-- exercise-library.sql (order relative to other migrations doesn't
-- matter otherwise). This file is large (it carries real image URLs
-- for hundreds of exercises) but it is still just SQL — same
-- paste-and-run process as every other file in this folder.
--
-- Merges in the free-exercise-db dataset
-- (github.com/yuhonas/free-exercise-db, public domain) on top of the
-- exercise_library this app already seeded from the exercemus/wger
-- import — real images for existing exercises, plus a handful of
-- genuinely new exercises the original import didn't have.
--
-- This is a MERGE, not a replacement, and it is safe to re-run:
--
--   - 871 of the 872 existing exercises were matched to a
--     free-exercise-db counterpart: 852 by an exact name match once
--     case/whitespace differences are normalized (these two datasets
--     share a common origin, so the overwhelming majority of names
--     line up exactly), plus 19 more resolved by hand where the name
--     differs but it's clearly the same movement — singular/plural
--     ("Hammer Curl" vs "Hammer Curls"), word order ("Barbell Decline
--     Bench Press" vs "Decline Barbell Bench Press"), punctuation
--     style ("Cable Hammer Curls (Rope Attachment)" vs
--     "... - Rope Attachment"), or a differently-worded label for the
--     same exercise confirmed by cross-checking equipment and
--     instructions text, not just the name (e.g. "Butterfly" —
--     equipment: machine, primary muscle: chest — is the same
--     exercise as the existing "Machine Chest Fly"; "Bench Press -
--     With Bands" turned out to be a near-word-for-word instructional
--     match for the existing "Band Bench Press", just ordered
--     differently). Only ONE existing exercise, "Dumbbell
--     Skullcrusher", has no free-exercise-db counterpart at all — it
--     keeps its NULL image, same honest-placeholder handling as
--     before.
--
--   - 5 genuinely new exercises get added as fresh rows — Bench Press
--     - Powerlifting, Kettlebell Halo, Kettlebell Halo with Overhead
--     Extension, Kettlebell Overhead Triceps Extension, and Parallel
--     Bar Dip — real, distinct movements confirmed by their
--     equipment/muscles/instructions genuinely not matching anything
--     already in the library (three of these five have no image in
--     free-exercise-db either, so they're added data-only, same as
--     every exercise already here that never had one).
--
-- Every existing exercise's own data (instructions, description,
-- category, muscle group, its original attribution) is left
-- completely untouched — step 1 below only ever ADDS an image to a
-- row that currently has none (its WHERE clause is `image_url is
-- null`, so re-running this file a second time is a safe no-op for
-- every row it already touched). It never overwrites or deletes
-- anything, including any custom exercise you've added yourself
-- outside of this import: a same-named custom row you already gave
-- its own image never gets touched, and step 2's five new rows use
-- ON CONFLICT (name) DO NOTHING, so a custom exercise you already
-- created under one of those exact names is left exactly as you made
-- it, never duplicated or overwritten.
--
-- Also adds a new image_urls text[] column alongside the existing
-- single image_url column — free-exercise-db has up to 2 images per
-- exercise (a start and end position), and the Exercise Library
-- screen now shows all of them when available; image_url keeps
-- holding just the first one, for anything that only ever reads that
-- single column.
--
-- Images are linked directly from free-exercise-db's own GitHub repo
-- (raw.githubusercontent.com) rather than re-hosted in this project's
-- own storage — the same "just link to it" approach this app already
-- takes with video_url's YouTube links.

alter table public.exercise_library
  add column if not exists image_urls text[] not null default '{}';

-- 1) Backfill images onto existing rows that don't have one yet.
update public.exercise_library el
set
  image_url = v.image_urls[1],
  image_urls = v.image_urls,
  attribution = el.attribution || ' Image from the free-exercise-db project (github.com/yuhonas/free-exercise-db), public domain.'
from (values
  ('3/4 Sit-Up', ARRAY['https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/3_4_Sit-Up/0.jpg','https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/3_4_Sit-Up/1.jpg']::text[]),
