-- 2) Add genuinely new exercises free-exercise-db has that the
--    original exercemus/wger import didn't.
insert into public.exercise_library
  (name, category, muscle_group, primary_muscles, secondary_muscles, equipment, instructions, description, video_url, image_url, image_urls, attribution)
values
('Bench Press - Powerlifting','powerlifting','arms',ARRAY['triceps']::text[],ARRAY['chest','forearms','lats','shoulders']::text[],ARRAY['barbell']::text[],ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.','Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],NULL,NULL,'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/0.jpg',ARRAY['https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/0.jpg','https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/1.jpg']::text[],'Exercise data and images from the free-exercise-db project (github.com/yuhonas/free-exercise-db), public domain.'),
('Kettlebell Halo','strength','shoulders',ARRAY['shoulders']::text[],ARRAY['traps','middle back','abs','triceps']::text[],ARRAY['kettlebell']::text[],ARRAY['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.','Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.','Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.','Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.','Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight.']::text[],NULL,NULL,NULL,ARRAY[]::text[],'Exercise data and images from the free-exercise-db project (github.com/yuhonas/free-exercise-db), public domain.'),
('Kettlebell Halo with Overhead Extension','strength','shoulders',ARRAY['shoulders','triceps']::text[],ARRAY['traps','middle back','abs']::text[],ARRAY['kettlebell']::text[],ARRAY['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.','Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.','From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.','Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.','Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.','Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises.']::text[],NULL,NULL,NULL,ARRAY[]::text[],'Exercise data and images from the free-exercise-db project (github.com/yuhonas/free-exercise-db), public domain.'),
('Kettlebell Overhead Triceps Extension','strength','arms',ARRAY['triceps']::text[],ARRAY['shoulders','abs']::text[],ARRAY['kettlebell']::text[],ARRAY['Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.','Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.','Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.','Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.','Keep your ribcage down and avoid arching your lower back as you extend.']::text[],NULL,NULL,NULL,ARRAY[]::text[],'Exercise data and images from the free-exercise-db project (github.com/yuhonas/free-exercise-db), public domain.'),
('Parallel Bar Dip','strength','arms',ARRAY['triceps']::text[],ARRAY['chest','shoulders']::text[],ARRAY['other']::text[],ARRAY['Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.','Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.','Reverse the motion by extending the elbow, pushing yourself back up into the starting position.','Repeat for the desired number of repetitions.']::text[],NULL,NULL,'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Parallel_Bar_Dip/0.jpg',ARRAY['https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Parallel_Bar_Dip/0.jpg','https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Parallel_Bar_Dip/1.jpg']::text[],'Exercise data and images from the free-exercise-db project (github.com/yuhonas/free-exercise-db), public domain.')
on conflict (name) do nothing;
